<?php
if (!defined('ABSPATH')) exit;
class SRWAI_Exporter {
 public static function init(){add_action('admin_post_srwai_export',array(__CLASS__,'export'));}
 public static function page(){if(!current_user_can('manage_options'))return;$types=SRWAI_Data_Importer::post_types();echo '<div class="wrap srwai-wrap row"><div class="srwai-hero col-md-8 col-sm-12"><div class="small-brand">SR All Import, Export & Bulk Deletion Plugin By Sifur Rahaman</div><h1>Export Data</h1><p>Export standard fields, detected custom post meta, taxonomies and featured image URLs.</p></div><div class="srwai-hero col-md-3 col-sm-12"><div class="small-brand">By Sifur Rahaman</div><h1>Donate Me</h1><a href="https://sifurrahaman.com/donate/" class="btn btn-primary">Donate Me</a></div><div class="row g-4"><div class="col-12 col-xl-8"><div class="card srwai-card"><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="srwai_export"><input type="hidden" name="_wpnonce" value="'.esc_attr(wp_create_nonce('srwai_export')).'"><div class="row g-3"><div class="col-12 col-md-6"><label class="form-label">Post Type</label><select class="form-select" name="post_type" required>';foreach($types as $t)echo '<option value="'.esc_attr($t->name).'">'.esc_html($t->labels->singular_name).' ('.esc_html($t->name).')</option>';echo '</select></div><div class="col-12 col-md-6"><label class="form-label">Format</label><select class="form-select" name="format"><option value="csv">CSV</option><option value="xlsx">XLSX</option><option value="xml">XML</option></select></div></div><button class="btn btn-success mt-4">Export</button></form></div></div><div class="col-12 col-xl-4"><div class="card srwai-card"><div class="card-body p-4"><h3 class="h5">Workflow</h3><ol class="mb-0 ps-3"><li class="mb-2">Select post type</li><li class="mb-2">Upload CSV / XLSX / XML</li><li class="mb-2">Inspect headers + sample only</li><li class="mb-2">Map fields</li><li class="mb-2">Start batch import</li><li>Review results</li></ol><div class="alert alert-success mt-4 mb-0"><h3 class="h5">Donate Me</h3><a href="https://sifurrahaman.com/donate/" target="_blank" class="text-white btn btn-success">Donate Me</a></div></div></div></div></div></div>';}
 public static function export(){if(!current_user_can('manage_options'))wp_die('Unauthorized');check_admin_referer('srwai_export');$type=sanitize_key(wp_unslash($_POST['post_type']??''));$format=sanitize_key(wp_unslash($_POST['format']??'csv'));if(!post_type_exists($type))wp_die('Invalid post type.');$ids=get_posts(array('post_type'=>$type,'post_status'=>'any','numberposts'=>-1,'fields'=>'ids'));$keys=SRWAI_Data_Importer::meta_keys($type);$tax=SRWAI_Data_Importer::taxonomies($type);$headers=array('ID','post_title','post_content','post_excerpt','post_status','post_date','post_author','featured_image');foreach($keys as $k)$headers[]='meta:'.$k;foreach($tax as $t)$headers[]='tax:'.$t->name;
 if($format==='csv'){ self::prepare_download(); header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="'.sanitize_file_name($type.'-export.csv').'"'); $csv=array(); $csv[]=self::csv_line($headers); foreach($ids as $id){ $csv[]=self::csv_line(self::row($id,$keys,$tax)); }
 // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- CSV is a file download and must not be HTML-escaped.
 echo implode("\r\n", $csv) . "\r\n";
 exit;
 }
 if($format==='xml'){nocache_headers();header('Content-Type:application/xml; charset=utf-8');header('Content-Disposition:attachment; filename='.$type.'-export.xml');echo '<?xml version="1.0" encoding="UTF-8"?><posts>';foreach($ids as $id){echo '<post>';foreach($headers as $i=>$h){$v=self::row($id,$keys,$tax)[$i]??'';echo '<field name="'.esc_attr($h).'">'.esc_html($v).'</field>';}echo '</post>';}echo '</posts>';exit;}
 if($format==='xlsx'){self::xlsx($type,$headers,$ids,$keys,$tax);exit;}wp_die('Unsupported format.');}
 private static function row($id,$keys,$tax){$r=array($id,get_the_title($id),get_post_field('post_content',$id),get_post_field('post_excerpt',$id),get_post_status($id),get_post_field('post_date',$id),get_post_field('post_author',$id),get_the_post_thumbnail_url($id,'full')?:'');foreach($keys as $k){$v=get_post_meta($id,$k,true);$r[]=is_scalar($v)?$v:wp_json_encode($v);}foreach($tax as $t)$r[]=implode('|',wp_get_post_terms($id,$t->name,array('fields'=>'names')));return $r;}
 private static function prepare_download(){ if(function_exists('wp_raise_memory_limit')){wp_raise_memory_limit('admin');} while(ob_get_level()>0){$status=ob_get_status(); if(!isset($status['del']) || !$status['del']){break;} ob_end_clean();} nocache_headers(); if(headers_sent()){wp_die('Cannot start export because output was already sent. Please check for PHP warnings or whitespace in plugin files.');} }
 private static function csv_line($row){$cells=array();foreach($row as $value){$value=is_scalar($value)?(string)$value:wp_json_encode($value);$cells[]= '"'.str_replace('"','""',$value).'"';}return implode(',',$cells);} private static function xlsx($type,$headers,$ids,$keys,$tax){if(!class_exists('ZipArchive'))wp_die('PHP ZipArchive extension is required for XLSX export.');$tmp=wp_tempnam($type.'.xlsx');$zip=new ZipArchive();if($zip->open($tmp,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)wp_die('Could not create XLSX.');$esc=function($s){return htmlspecialchars((string)$s,ENT_XML1|ENT_COMPAT,'UTF-8');};$cols=count($headers);$xml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';$all=array($headers);foreach($ids as $id)$all[]=self::row($id,$keys,$tax);$rn=1;foreach($all as $row){$xml.='<row r="'.$rn.'">';foreach($row as $ci=>$v){$ref=self::excel_col($ci+1).$rn;$xml.='<c r="'.$ref.'" t="inlineStr"><is><t xml:space="preserve">'.$esc($v).'</t></is></c>';}$xml.='</row>';$rn++;}$xml.='</sheetData></worksheet>';$zip->addFromString('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');$zip->addFromString('_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');$zip->addFromString('xl/workbook.xml','<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Export" sheetId="1" r:id="rId1"/></sheets></workbook>');$zip->addFromString('xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');$zip->addFromString('xl/worksheets/sheet1.xml',$xml);$zip->close(); require_once ABSPATH.'wp-admin/includes/file.php'; global $wp_filesystem; if(!function_exists('WP_Filesystem') || !WP_Filesystem()){ wp_delete_file($tmp); wp_die('Could not initialize the WordPress filesystem.'); } if(!$wp_filesystem){ wp_delete_file($tmp); wp_die('Could not initialize the WordPress filesystem.'); } $contents=$wp_filesystem->get_contents($tmp); $size=$wp_filesystem->size($tmp); wp_delete_file($tmp); if($contents===false){wp_die('Could not read the generated XLSX file.');} self::prepare_download(); header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'); header('Content-Disposition: attachment; filename="'.sanitize_file_name($type.'-export.xlsx').'"'); if($size!==false){header('Content-Length: '.(string)$size);}

 // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- XLSX is binary output and must not be HTML-escaped.
 echo $contents;
 exit;
}
 private static function excel_col($n){$s='';while($n>0){$n--; $s=chr(65+($n%26)).$s;$n=intdiv($n,26);}return $s;}
}
